"""Embedded LAN-only PulseDeck Admin interface."""

ADMIN_HTML = r'''<!doctype html>
<html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>PulseDeck Admin</title>
<style>
:root{color-scheme:dark;--bg:#0b0e13;--panel:#141922;--panel2:#1a2130;--panel3:#0e131b;--text:#e9edf4;--muted:#8e99a9;--line:#2a3444;--line2:#344156;--good:#62d38b;--warn:#f4c56b;--bad:#ff7474;--accent:#7aa2ff;--accent2:#9bb8ff;--shadow:0 14px 40px rgba(0,0,0,.24)}
*{box-sizing:border-box}html{background:var(--bg)}body{margin:0;background:var(--bg);color:var(--text);font:14px/1.45 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}button,input,select{font:inherit}button{cursor:pointer}.shell{max-width:1180px;margin:auto;padding:22px}.top{display:flex;gap:20px;justify-content:space-between;align-items:center;margin-bottom:14px}.brand h1{font-size:24px;line-height:1.1;margin:0}.brand p{margin:4px 0 0;color:var(--muted);font-size:12px}.top-actions{display:flex;gap:8px;align-items:center}.nav{display:flex;gap:6px;padding:5px;background:#10151d;border:1px solid var(--line);border-radius:11px;margin:0 0 14px;overflow:auto}.nav button{border:0;background:transparent;color:var(--muted);padding:8px 12px;border-radius:7px;white-space:nowrap;font-weight:650}.nav button.active{background:var(--panel2);color:var(--text)}.view{display:none}.view.active{display:block}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:10px}.card{background:var(--panel);border:1px solid var(--line);border-radius:11px;padding:15px;margin-bottom:10px;box-shadow:0 0 0 rgba(0,0,0,0)}.metric-card{min-height:102px}.eyebrow{color:var(--muted);font-size:11px;text-transform:uppercase;letter-spacing:.04em}.metric{font-size:21px;font-weight:700;margin-top:4px}.meta{color:var(--muted);font-size:12px;margin-top:4px}.ok{color:var(--good)}.warn{color:var(--warn)}.bad{color:var(--bad)}.muted{color:var(--muted)}h2{font-size:15px;margin:0}h3{font-size:13px;margin:0}.section-head{display:flex;justify-content:space-between;gap:12px;align-items:flex-start;margin-bottom:13px}.section-head p{margin:3px 0 0;color:var(--muted);font-size:12px}.pill{display:inline-flex;align-items:center;gap:6px;padding:4px 8px;border:1px solid var(--line);background:var(--panel3);border-radius:999px;color:var(--muted);font-size:11px}.pill.good{color:var(--good);border-color:rgba(98,211,139,.35)}.pill.warn{color:var(--warn);border-color:rgba(244,197,107,.35)}.pill.bad{color:var(--bad);border-color:rgba(255,116,116,.35)}.dot{width:7px;height:7px;border-radius:50%;background:currentColor;display:inline-block}.services{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.service{display:flex;justify-content:space-between;gap:14px;padding:14px;border:1px solid var(--line);background:var(--panel3);border-radius:9px}.service-title{display:flex;align-items:center;gap:8px;font-weight:700}.service-detail{font-size:12px;color:var(--muted);margin-top:5px}.service-side{display:flex;flex-direction:column;gap:8px;align-items:flex-end;justify-content:space-between}.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px 12px}.span2{grid-column:1/-1}.field label{display:flex;justify-content:space-between;gap:8px;color:var(--muted);font-size:11px;margin:0 0 5px}.hint{color:#6f7a8b;font-size:10px}.field input,.field select{width:100%;background:var(--panel3);border:1px solid var(--line);color:var(--text);padding:9px 10px;border-radius:7px;outline:none}.field input:focus,.field select:focus{border-color:var(--accent)}.field input.invalid,.field select.invalid{border-color:var(--bad)}.field-error{min-height:15px;font-size:10px;color:var(--bad);margin-top:3px}.toggle{display:flex;align-items:center;gap:8px;font-size:12px}.toggle input{accent-color:var(--accent)}.subcard{background:var(--panel3);border:1px solid var(--line);border-radius:9px;padding:12px;margin:10px 0}.subhead{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:9px}.actions{display:flex;gap:7px;align-items:center;flex-wrap:wrap;margin-top:12px}.btn{border:0;border-radius:7px;padding:8px 11px;background:var(--accent);color:#07101f;font-weight:750}.btn:hover{background:var(--accent2)}.btn.secondary{background:var(--panel2);color:var(--text);border:1px solid var(--line)}.btn.ghost{background:transparent;color:var(--muted);border:1px solid var(--line)}.btn:disabled{opacity:.45;cursor:not-allowed}.inline-status{font-size:11px;color:var(--muted)}.activity{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.activity-item{background:var(--panel3);border:1px solid var(--line);border-radius:8px;padding:10px}.activity-value{font-weight:700;margin-top:3px}.error-box{display:none;margin-top:9px;padding:10px;border:1px solid rgba(255,116,116,.35);background:rgba(255,116,116,.06);border-radius:8px;color:#ffc0c0;font-size:12px}.error-box.show{display:block}.key-state{display:flex;gap:8px;align-items:center;padding:8px 10px;background:var(--panel3);border:1px solid var(--line);border-radius:7px;color:var(--muted);font-size:11px}.login-wrap{max-width:430px;margin:12vh auto}.login-wrap .card{box-shadow:var(--shadow)}.toast-stack{position:fixed;right:18px;bottom:18px;z-index:20;display:flex;flex-direction:column;gap:8px;max-width:360px}.toast{background:#171e29;border:1px solid var(--line2);box-shadow:var(--shadow);padding:11px 13px;border-radius:9px;animation:toastin .15s ease-out}.toast.good{border-left:3px solid var(--good)}.toast.bad{border-left:3px solid var(--bad)}.toast.warn{border-left:3px solid var(--warn)}.toast strong{display:block;font-size:12px}.toast span{display:block;color:var(--muted);font-size:11px;margin-top:2px}.skeleton{opacity:.55}.hide{display:none!important}@keyframes toastin{from{transform:translateY(7px);opacity:0}to{transform:none;opacity:1}}@media(max-width:900px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}.services{grid-template-columns:1fr}}@media(max-width:640px){.shell{padding:12px}.top{align-items:flex-start}.brand h1{font-size:20px}.grid,.form-grid,.activity{grid-template-columns:1fr}.span2{grid-column:auto}.card{padding:12px}.service{flex-direction:column}.service-side{align-items:flex-start}.nav{position:sticky;top:0;z-index:8;background:rgba(16,21,29,.96)}.toast-stack{left:12px;right:12px;bottom:12px;max-width:none}}
</style></head><body><main class="shell">
<div class="top"><div class="brand"><h1>PulseDeck Admin</h1><p>Administration locale du hub</p></div><div class="top-actions"><span id="connectionBadge" class="pill hide"><span class="dot"></span><span></span></span><button id="logout" class="btn ghost hide">Déconnexion</button></div></div>
<section id="login" class="login-wrap hide"><div class="card"><div class="section-head"><div><h2>Connexion</h2><p>Accès administrateur local</p></div></div><div class="field"><label>Mot de passe</label><input id="loginPassword" type="password" autocomplete="current-password"></div><div class="actions"><button id="loginButton" class="btn">Connexion</button><span id="loginStatus" class="inline-status"></span></div></div></section>
<section id="app" class="hide">
<nav class="nav" aria-label="Navigation"><button data-view="dashboard" class="active">Vue d’ensemble</button><button data-view="weather">Weather</button><button data-view="news">News</button><button data-view="services">Services</button><button data-view="security">Sécurité</button></nav>
<section class="view active" data-view-panel="dashboard">
<div class="grid">
<div class="card metric-card"><div class="eyebrow">Hub</div><div id="hubVersion" class="metric">—</div><div id="hubUptime" class="meta">—</div></div>
<div class="card metric-card"><div class="eyebrow">MQTT</div><div id="mqttState" class="metric">—</div><div id="mqttTarget" class="meta">—</div></div>
<div class="card metric-card"><div class="eyebrow">Weather</div><div id="weatherState" class="metric">—</div><div id="weatherDetail" class="meta">—</div></div>
<div class="card metric-card"><div class="eyebrow">News</div><div id="newsState" class="metric">—</div><div id="newsDetail" class="meta">—</div></div>
<div class="card metric-card"><div class="eyebrow">Système</div><div id="systemMemory" class="metric">—</div><div id="systemDisk" class="meta">—</div></div>
</div>
<div class="card"><div class="section-head"><div><h2>Services</h2><p>État et ordre de mise en place des collectors</p></div><button class="btn ghost" data-go="services">Tout afficher</button></div><div id="dashboardServices" class="services"></div></div>
<div class="card"><div class="section-head"><div><h2>Activité Weather</h2><p>Dernières collectes réussies</p></div><button class="btn ghost" data-go="weather">Configurer</button></div><div id="dashboardActivity" class="activity"></div><div id="dashboardError" class="error-box"></div></div>
<div class="card"><div class="section-head"><div><h2>Activité News</h2><p>Dernier snapshot GNews publié</p></div><button class="btn ghost" data-go="news">Configurer</button></div><div id="dashboardNewsActivity" class="activity"></div><div id="dashboardNewsError" class="error-box"></div></div>
</section>
<section class="view" data-view-panel="weather">
<div class="card"><div class="section-head"><div><h2>Weather · OpenWeather One Call 4.0</h2><p>Configuration, test fournisseur et rechargement à chaud</p></div><label class="toggle"><input id="weatherEnabled" type="checkbox">Collector activé</label></div>
<div class="subcard"><div class="subhead"><h3>Localisation</h3><span class="pill">One Call 4.0</span></div><div class="form-grid"><div class="field"><label>Lieu à rechercher <span class="hint">ville, pays</span></label><input id="locationQuery" placeholder="Yutz, France"><div class="field-error"></div></div><div class="field"><label>Résultat</label><select id="locationResult"><option value="">Coordonnées actuelles</option></select><div class="field-error"></div></div><div class="field"><label>Latitude</label><input id="latitude" type="number" step="any"><div id="latitudeError" class="field-error"></div></div><div class="field"><label>Longitude</label><input id="longitude" type="number" step="any"><div id="longitudeError" class="field-error"></div></div><div class="field span2"><label>Nom affiché</label><input id="locationName"><div class="field-error"></div></div></div><div class="actions"><button id="geocodeButton" class="btn secondary">Résoudre le lieu</button></div></div>
<div class="subcard"><div class="subhead"><h3>Accès fournisseur</h3><span id="keyBadge" class="pill">Clé inconnue</span></div><div class="form-grid"><div class="field span2"><label>Clé API OpenWeather <span class="hint">laisser vide pour conserver la clé actuelle</span></label><input id="apiKey" type="password" autocomplete="new-password" placeholder="••••••••••••"><div id="apiKeyError" class="field-error"></div></div><div class="field"><label>Langue</label><input id="lang" value="fr"><div id="langError" class="field-error"></div></div><div class="field"><label>Timeout HTTP <span class="hint">secondes</span></label><input id="requestTimeout" type="number" min="1" max="60"><div id="timeoutError" class="field-error"></div></div></div></div>
<div class="subcard"><div class="subhead"><h3>Cadences</h3><span class="pill">minimum 10 min</span></div><div class="form-grid"><div class="field"><label>Current <span class="hint">minutes</span></label><input id="currentMinutes" type="number" min="10" step="1"><div id="currentError" class="field-error"></div></div><div class="field"><label>Hourly <span class="hint">minutes</span></label><input id="hourlyMinutes" type="number" min="10" step="1"><div id="hourlyError" class="field-error"></div></div><div class="field"><label>Daily <span class="hint">minutes</span></label><input id="dailyMinutes" type="number" min="10" step="1"><div id="dailyError" class="field-error"></div></div><div class="field"><label>Horizons</label><div class="key-state">48 heures · 10 jours</div><div class="field-error"></div></div></div></div>
<div class="actions"><button id="testWeatherButton" class="btn secondary">Tester l’API</button><button id="saveWeatherButton" class="btn">Enregistrer</button><span id="weatherFormStatus" class="inline-status">L’enregistrement teste le fournisseur avant application.</span></div>
</div>
<div class="card"><div class="section-head"><div><h2>Dernière activité</h2><p>État runtime du collector</p></div><span id="weatherRuntimeBadge" class="pill">—</span></div><div id="weatherActivity" class="activity"></div><div id="weatherError" class="error-box"></div></div>
</section>
<section class="view" data-view-panel="news">
<div class="card"><div class="section-head"><div><h2>News · GNews</h2><p>HTTPS uniquement · authentification fournisseur via header X-Api-Key</p></div><label class="toggle"><input id="newsEnabled" type="checkbox">Collector activé</label></div>
<div class="subcard"><div class="subhead"><h3>Flux</h3><span class="pill">GNews API v4</span></div><div class="form-grid"><div class="field"><label>Mode</label><select id="newsMode"><option value="top-headlines">Top headlines</option><option value="search">Search</option></select><div id="newsModeError" class="field-error"></div></div><div class="field"><label>Catégorie <span class="hint">top-headlines</span></label><select id="newsCategory"><option value="general">general</option><option value="world">world</option><option value="nation">nation</option><option value="business">business</option><option value="technology">technology</option><option value="entertainment">entertainment</option><option value="sports">sports</option><option value="science">science</option><option value="health">health</option></select><div id="newsCategoryError" class="field-error"></div></div><div class="field span2"><label>Requête <span class="hint" id="newsQueryHint">optionnelle pour top-headlines</span></label><input id="newsQuery" maxlength="200" placeholder="ex. intelligence artificielle"><div id="newsQueryError" class="field-error"></div></div><div class="field"><label>Langue <span class="hint">code ISO, vide = tous</span></label><input id="newsLang" maxlength="2" placeholder="fr"><div id="newsLangError" class="field-error"></div></div><div class="field"><label>Pays <span class="hint">code ISO, vide = tous</span></label><input id="newsCountry" maxlength="2" placeholder="fr"><div id="newsCountryError" class="field-error"></div></div><div class="field"><label>Articles par snapshot <span class="hint">1–100, selon plan</span></label><input id="newsMaxArticles" type="number" min="1" max="100" step="1"><div id="newsMaxError" class="field-error"></div></div><div class="field"><label>Cadence <span class="hint">minutes</span></label><input id="newsIntervalMinutes" type="number" min="5" step="1"><div id="newsIntervalError" class="field-error"></div></div></div></div>
<div class="subcard"><div class="subhead"><h3>Accès fournisseur</h3><span id="newsKeyBadge" class="pill">Clé inconnue</span></div><div class="form-grid"><div class="field span2"><label>Clé API GNews <span class="hint">laisser vide pour conserver la clé actuelle</span></label><input id="newsApiKey" type="password" autocomplete="new-password" placeholder="••••••••••••"><div id="newsApiKeyError" class="field-error"></div></div><div class="field"><label>Timeout HTTP <span class="hint">secondes</span></label><input id="newsRequestTimeout" type="number" min="1" max="60"><div id="newsTimeoutError" class="field-error"></div></div><div class="field"><label>Transport / Auth</label><div class="key-state">HTTPS · X-Api-Key</div><div class="field-error"></div></div></div></div>
<div class="actions"><button id="testNewsButton" class="btn secondary">Tester l’API</button><button id="saveNewsButton" class="btn">Enregistrer</button><span id="newsFormStatus" class="inline-status">L’enregistrement teste GNews avant activation.</span></div>
</div>
<div class="card"><div class="section-head"><div><h2>Dernière activité</h2><p>État runtime du collector News</p></div><span id="newsRuntimeBadge" class="pill">—</span></div><div id="newsActivity" class="activity"></div><div id="newsError" class="error-box"></div></div>
</section>
<section class="view" data-view-panel="services"><div class="card"><div class="section-head"><div><h2>Services PulseDeck</h2><p>Les panneaux utilisent un catalogue commun pour préparer l’ajout des prochains collectors.</p></div></div><div id="servicesList" class="services"></div></div></section>
<section class="view" data-view-panel="security"><div class="card"><div class="section-head"><div><h2>Sécurité Admin</h2><p>Le mot de passe est stocké sous forme de hash ; les sessions sont signées.</p></div></div><div class="form-grid"><div class="field"><label>Mot de passe actuel</label><input id="currentPassword" type="password" autocomplete="current-password"><div class="field-error"></div></div><div class="field"><label>Nouveau mot de passe <span class="hint">12 caractères minimum</span></label><input id="newPassword" type="password" autocomplete="new-password"><div id="passwordError" class="field-error"></div></div></div><div class="actions"><button id="changePasswordButton" class="btn secondary">Changer le mot de passe</button><span id="passwordStatus" class="inline-status"></span></div></div></section>
</section>
</main><div id="toasts" class="toast-stack" aria-live="polite"></div>
<script>
const $=id=>document.getElementById(id);
const state={status:null,services:[],weather:null,news:null,busy:false};
const api=(url,opt={})=>fetch(url,{credentials:'same-origin',headers:{'Content-Type':'application/json','X-PulseDeck-CSRF':'1',...(opt.headers||{})},...opt});
function esc(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function fmtAge(ts){if(!ts)return 'jamais';const s=Math.max(0,Math.floor(Date.now()/1000-ts));if(s<60)return s+' s';if(s<3600)return Math.floor(s/60)+' min';if(s<86400)return Math.floor(s/3600)+' h';return Math.floor(s/86400)+' j'}
function fmtDuration(s){s=Math.max(0,Math.floor(s||0));if(s<60)return s+' s';const m=Math.floor(s/60);if(m<60)return m+' min';const h=Math.floor(m/60),rm=m%60;if(h<24)return h+' h'+(rm?' '+rm+' min':'');const d=Math.floor(h/24),rh=h%24;return d+' j'+(rh?' '+rh+' h':'')}
function toast(kind,title,message=''){const box=document.createElement('div');box.className='toast '+kind;box.innerHTML='<strong>'+esc(title)+'</strong>'+(message?'<span>'+esc(message)+'</span>':'');$('toasts').appendChild(box);setTimeout(()=>box.remove(),4500)}
function setBusy(button,busy,label){button.disabled=busy;if(busy){button.dataset.label=button.textContent;button.textContent=label||'Traitement…'}else if(button.dataset.label){button.textContent=button.dataset.label;delete button.dataset.label}}
function showView(name){document.querySelectorAll('[data-view-panel]').forEach(x=>x.classList.toggle('active',x.dataset.viewPanel===name));document.querySelectorAll('.nav [data-view]').forEach(x=>x.classList.toggle('active',x.dataset.view===name));history.replaceState(null,'','#'+name)}
function statusClass(value){if(value==='online')return 'good';if(value==='planned'||value==='starting'||value==='stopped')return 'warn';if(value==='disabled')return '';return 'bad'}
function statusLabel(value){return ({online:'online',offline:'offline',disabled:'désactivé',planned:'à venir',starting:'démarrage',stopped:'arrêté'})[value]||value||'—'}
function serviceCard(s,compact=false){const meta=[s.provider,s.transport,s.auth].filter(Boolean).join(' · ');const action=s.available&&s.view?'<button class="btn ghost" data-service-view="'+esc(s.view)+'">Ouvrir</button>':'<span class="pill">À venir</span>';return '<div class="service"><div><div class="service-title"><span class="dot '+statusClass(s.state)+'" style="color:var(--'+(statusClass(s.state)==='good'?'good':statusClass(s.state)==='bad'?'bad':statusClass(s.state)==='warn'?'warn':'muted')+')"></span>'+esc(s.label)+'</div><div class="service-detail">'+esc(meta||'Contrat à définir')+'</div></div><div class="service-side"><span class="pill '+statusClass(s.state)+'">'+esc(statusLabel(s.state))+'</span>'+(!compact?action:'')+'</div></div>'}
function renderServices(){const all=state.services;$('servicesList').innerHTML=all.map(s=>serviceCard(s,false)).join('');$('dashboardServices').innerHTML=all.slice(0,4).map(s=>serviceCard(s,true)).join('');document.querySelectorAll('[data-service-view]').forEach(b=>b.onclick=()=>showView(b.dataset.serviceView))}
function activityHtml(w){return '<div class="activity-item"><div class="eyebrow">Current</div><div class="activity-value">'+esc(fmtAge(w.last_current))+'</div><div class="meta">dernière réussite</div></div><div class="activity-item"><div class="eyebrow">Hourly</div><div class="activity-value">'+esc(fmtAge(w.last_hourly))+'</div><div class="meta">'+esc((w.hourly_records??'—')+' / 48 h')+'</div></div><div class="activity-item"><div class="eyebrow">Daily</div><div class="activity-value">'+esc(fmtAge(w.last_daily))+'</div><div class="meta">'+esc((w.daily_records??'—')+' / 10 j')+'</div></div>'}
function renderWeatherHealth(w){const html=activityHtml(w);$('weatherActivity').innerHTML=html;$('dashboardActivity').innerHTML=html;const badge=$('weatherRuntimeBadge');badge.className='pill '+statusClass(w.state);badge.innerHTML='<span class="dot"></span>'+esc(statusLabel(w.state));const text=w.last_error?((w.last_error_kind||'collector')+' · '+fmtAge(w.last_error_at)+' · '+w.last_error):'';for(const id of ['weatherError','dashboardError']){const el=$(id);el.textContent=text;el.classList.toggle('show',Boolean(text))}}
function renderNewsHealth(n){const html='<div class="activity-item"><div class="eyebrow">Dernière réussite</div><div class="activity-value">'+esc(fmtAge(n.last_success))+'</div><div class="meta">snapshot GNews</div></div><div class="activity-item"><div class="eyebrow">Articles</div><div class="activity-value">'+esc(n.article_count??'—')+'</div><div class="meta">dernier snapshot</div></div><div class="activity-item"><div class="eyebrow">État</div><div class="activity-value">'+esc(statusLabel(n.state))+'</div><div class="meta">collector</div></div>';$('newsActivity').innerHTML=html;$('dashboardNewsActivity').innerHTML=html;const badge=$('newsRuntimeBadge');badge.className='pill '+statusClass(n.state);badge.innerHTML='<span class="dot"></span>'+esc(statusLabel(n.state));const text=n.last_error?(fmtAge(n.last_error_at)+' · '+n.last_error):'';for(const id of ['newsError','dashboardNewsError']){const el=$(id);el.textContent=text;el.classList.toggle('show',Boolean(text))}}
function renderStatus(s){state.status=s;$('hubVersion').textContent='v'+s.version;$('hubUptime').textContent='uptime '+fmtDuration(s.uptime_seconds);$('mqttState').textContent=s.mqtt.connected?'online':'offline';$('mqttState').className='metric '+(s.mqtt.connected?'ok':'bad');$('mqttTarget').textContent=s.mqtt.host+':'+s.mqtt.port+' · '+s.mqtt.namespace;const w=s.weather;$('weatherState').textContent=statusLabel(w.state);$('weatherState').className='metric '+(w.state==='online'?'ok':(w.state==='offline'?'bad':''));$('weatherDetail').textContent=(w.hourly_records??'—')+' h · '+(w.daily_records??'—')+' j';const n=s.news;$('newsState').textContent=statusLabel(n.state);$('newsState').className='metric '+(n.state==='online'?'ok':(n.state==='offline'?'bad':''));$('newsDetail').textContent=(n.article_count??'—')+' article(s)';$('systemMemory').textContent=s.system.memory_available_mb+' MiB libres';$('systemDisk').textContent=s.system.disk_free_gb+' / '+s.system.disk_total_gb+' GiB libres';renderWeatherHealth(w);renderNewsHealth(n);const b=$('connectionBadge');b.classList.remove('hide');b.className='pill '+(s.mqtt.connected?'good':'bad');b.innerHTML='<span class="dot"></span><span>'+(s.mqtt.connected?'MQTT online':'MQTT offline')+'</span>'}
async function login(){const btn=$('loginButton');$('loginStatus').textContent='';setBusy(btn,true,'Connexion…');try{const r=await api('/api/auth/login',{method:'POST',body:JSON.stringify({password:$('loginPassword').value})});if(!r.ok){$('loginStatus').textContent='Identifiants invalides';return}$('loginPassword').value='';await boot();toast('good','Connexion établie')}finally{setBusy(btn,false)}}
async function logout(){await api('/api/auth/logout',{method:'POST',body:'{}'});location.reload()}
async function boot(){const r=await api('/api/status');if(r.status===401){$('login').classList.remove('hide');$('app').classList.add('hide');$('logout').classList.add('hide');$('connectionBadge').classList.add('hide');return}if(!r.ok){toast('bad','Admin indisponible','Impossible de lire le statut du hub');return}$('login').classList.add('hide');$('app').classList.remove('hide');$('logout').classList.remove('hide');renderStatus(await r.json());await Promise.all([loadWeather(),loadNews(),loadServices()]);const wanted=location.hash.replace('#','');showView(['dashboard','weather','news','services','security'].includes(wanted)?wanted:'dashboard')}
async function loadServices(){const r=await api('/api/services');if(!r.ok)return;state.services=(await r.json()).services||[];renderServices()}
async function loadWeather(){const r=await api('/api/weather/config');if(!r.ok)return;const w=await r.json();state.weather=w;$('weatherEnabled').checked=w.enabled;$('latitude').value=w.latitude??'';$('longitude').value=w.longitude??'';$('locationName').value=w.location_name||'';$('lang').value=w.lang;$('requestTimeout').value=w.request_timeout;$('currentMinutes').value=Math.round(w.current_interval/60);$('hourlyMinutes').value=Math.round(w.hourly_interval/60);$('dailyMinutes').value=Math.round(w.daily_interval/60);const kb=$('keyBadge');kb.className='pill '+(w.api_key_configured?'good':'warn');kb.innerHTML='<span class="dot"></span>'+(w.api_key_configured?'Clé configurée':'Clé absente');validateWeather(false)}
async function loadNews(){const r=await api('/api/news/config');if(!r.ok)return;const n=await r.json();state.news=n;$('newsEnabled').checked=n.enabled;$('newsMode').value=n.mode;$('newsCategory').value=n.category;$('newsQuery').value=n.query||'';$('newsLang').value=n.lang||'';$('newsCountry').value=n.country||'';$('newsMaxArticles').value=n.max_articles;$('newsIntervalMinutes').value=Math.round(n.interval/60);$('newsRequestTimeout').value=n.request_timeout;const kb=$('newsKeyBadge');kb.className='pill '+(n.api_key_configured?'good':'warn');kb.innerHTML='<span class="dot"></span>'+(n.api_key_configured?'Clé configurée':'Clé absente');updateNewsMode();validateNews(false)}
function updateNewsMode(){const search=$('newsMode').value==='search';$('newsCategory').disabled=search;$('newsQueryHint').textContent=search?'requise pour search':'optionnelle pour top-headlines'}
function validCode(value){return value===''||/^[A-Za-z]{2}$/.test(value)}
function validateNews(show=true){let ok=true;[['newsMode','newsModeError'],['newsCategory','newsCategoryError'],['newsQuery','newsQueryError'],['newsLang','newsLangError'],['newsCountry','newsCountryError'],['newsMaxArticles','newsMaxError'],['newsIntervalMinutes','newsIntervalError'],['newsApiKey','newsApiKeyError'],['newsRequestTimeout','newsTimeoutError']].forEach(([a,b])=>clearField(a,b));const enabled=$('newsEnabled').checked,mode=$('newsMode').value,query=$('newsQuery').value.trim();if(mode==='search'&&!query)ok=invalid('newsQuery','newsQueryError','Requête requise en mode Search');if(query.length>200)ok=invalid('newsQuery','newsQueryError','200 caractères maximum');if(!validCode($('newsLang').value.trim()))ok=invalid('newsLang','newsLangError','Code langue sur 2 lettres ou vide');if(!validCode($('newsCountry').value.trim()))ok=invalid('newsCountry','newsCountryError','Code pays sur 2 lettres ou vide');const max=Number($('newsMaxArticles').value);if(!Number.isInteger(max)||max<1||max>100)ok=invalid('newsMaxArticles','newsMaxError','Valeur entière de 1 à 100');const interval=Number($('newsIntervalMinutes').value);if(!Number.isInteger(interval)||interval<5)ok=invalid('newsIntervalMinutes','newsIntervalError','Minimum 5 minutes');const timeout=Number($('newsRequestTimeout').value);if(!Number.isInteger(timeout)||timeout<1||timeout>60)ok=invalid('newsRequestTimeout','newsTimeoutError','Valeur entière de 1 à 60 s');if(enabled&&!(state.news?.api_key_configured)&&!$('newsApiKey').value.trim())ok=invalid('newsApiKey','newsApiKeyError','Clé GNews requise pour activer News');if(show&&!ok)toast('bad','Formulaire News incomplet','Corriger les champs signalés');return ok}
function newsBody(){return {enabled:$('newsEnabled').checked,mode:$('newsMode').value,category:$('newsCategory').value,query:$('newsQuery').value.trim(),lang:$('newsLang').value.trim().toLowerCase(),country:$('newsCountry').value.trim().toLowerCase(),max_articles:Number($('newsMaxArticles').value),interval:Number($('newsIntervalMinutes').value)*60,request_timeout:Number($('newsRequestTimeout').value),api_key:$('newsApiKey').value.trim()||null}}
async function testNews(){if(!validateNews())return;const btn=$('testNewsButton');$('newsFormStatus').textContent='Test GNews en cours…';setBusy(btn,true,'Test…');try{const r=await api('/api/news/test',{method:'POST',body:JSON.stringify(newsBody())});const d=await r.json();if(!r.ok){$('newsFormStatus').textContent=d.detail||'Échec';toast('bad','Test GNews échoué',d.detail||'Erreur fournisseur');return}const msg='GNews OK · '+d.article_count+' article(s)'+(d.first_title?' · '+d.first_title:'');$('newsFormStatus').textContent=msg;toast('good','Test News réussi',msg)}finally{setBusy(btn,false)}}
async function saveNews(){if(!validateNews())return;const btn=$('saveNewsButton');$('newsFormStatus').textContent='Validation et application transactionnelle…';setBusy(btn,true,'Enregistrement…');try{const r=await api('/api/news/config',{method:'POST',body:JSON.stringify(newsBody())});const d=await r.json();if(!r.ok){$('newsFormStatus').textContent=d.detail||'Échec';toast('bad','Configuration News non appliquée',d.detail||'Erreur');return}$('newsApiKey').value='';$('newsFormStatus').textContent='Configuration appliquée';toast('good','News mis à jour','Configuration sauvegardée et collector rechargé');await Promise.all([loadNews(),loadServices()]);setTimeout(refreshStatus,350)}finally{setBusy(btn,false)}}
function clearField(id,errorId){$(id).classList.remove('invalid');if(errorId)$(errorId).textContent=''}
function invalid(id,errorId,message){$(id).classList.add('invalid');if(errorId)$(errorId).textContent=message;return false}
function validateWeather(show=true){let ok=true;[['latitude','latitudeError'],['longitude','longitudeError'],['apiKey','apiKeyError'],['lang','langError'],['requestTimeout','timeoutError'],['currentMinutes','currentError'],['hourlyMinutes','hourlyError'],['dailyMinutes','dailyError']].forEach(([a,b])=>clearField(a,b));const enabled=$('weatherEnabled').checked;const lat=$('latitude').value===''?null:Number($('latitude').value),lon=$('longitude').value===''?null:Number($('longitude').value);if(enabled&&(lat===null||!Number.isFinite(lat)||lat<-90||lat>90))ok=invalid('latitude','latitudeError','Latitude requise entre -90 et 90');if(enabled&&(lon===null||!Number.isFinite(lon)||lon<-180||lon>180))ok=invalid('longitude','longitudeError','Longitude requise entre -180 et 180');if(enabled&&!(state.weather?.api_key_configured)&&!$('apiKey').value.trim())ok=invalid('apiKey','apiKeyError','Clé API requise pour activer Weather');if(!$('lang').value.trim())ok=invalid('lang','langError','Langue requise');const timeout=Number($('requestTimeout').value);if(!Number.isInteger(timeout)||timeout<1||timeout>60)ok=invalid('requestTimeout','timeoutError','Valeur entière de 1 à 60 s');for(const [id,eid] of [['currentMinutes','currentError'],['hourlyMinutes','hourlyError'],['dailyMinutes','dailyError']]){const v=Number($(id).value);if(!Number.isInteger(v)||v<10)ok=invalid(id,eid,'Minimum 10 minutes')}if(show&&!ok)toast('bad','Formulaire incomplet','Corriger les champs signalés');return ok}
function weatherBody(){return {enabled:$('weatherEnabled').checked,latitude:$('latitude').value===''?null:Number($('latitude').value),longitude:$('longitude').value===''?null:Number($('longitude').value),location_name:$('locationName').value.trim(),api_key:$('apiKey').value.trim()||null,lang:$('lang').value.trim(),current_interval:Number($('currentMinutes').value)*60,hourly_interval:Number($('hourlyMinutes').value)*60,daily_interval:Number($('dailyMinutes').value)*60,hourly_hours:48,daily_days:10,request_timeout:Number($('requestTimeout').value)}}
async function geocode(){const q=$('locationQuery').value.trim();if(!q){toast('warn','Lieu requis','Saisir une ville ou un lieu à rechercher');return}const btn=$('geocodeButton');setBusy(btn,true,'Recherche…');try{const r=await api('/api/weather/geocode',{method:'POST',body:JSON.stringify({query:q,api_key:$('apiKey').value.trim()||null})});const d=await r.json();if(!r.ok){toast('bad','Géocodage impossible',d.detail||'Erreur fournisseur');return}const sel=$('locationResult');sel.innerHTML='';(d.results||[]).forEach((x,i)=>{const o=document.createElement('option');o.value=i;o.textContent=x.label;sel.appendChild(o)});sel.onchange=()=>pickLocation(d.results[Number(sel.value)]);if(d.results?.length){pickLocation(d.results[0]);toast('good','Lieu résolu',d.results.length+' résultat(s)')}else toast('warn','Aucun résultat')}finally{setBusy(btn,false)}}
function pickLocation(x){if(!x)return;$('latitude').value=x.latitude;$('longitude').value=x.longitude;$('locationName').value=x.label;validateWeather(false)}
async function testWeather(){if(!validateWeather())return;const btn=$('testWeatherButton');$('weatherFormStatus').textContent='Test fournisseur en cours…';setBusy(btn,true,'Test…');try{const r=await api('/api/weather/test',{method:'POST',body:JSON.stringify(weatherBody())});const d=await r.json();if(!r.ok){$('weatherFormStatus').textContent=d.detail||'Échec';toast('bad','Test Weather échoué',d.detail||'Erreur fournisseur');return}const msg=d.disabled?'Collector désactivé · configuration valide':('OpenWeather OK · '+d.temperature_c+' °C · '+d.hourly_records+' h testée(s)');$('weatherFormStatus').textContent=msg;toast('good','Test Weather réussi',msg)}finally{setBusy(btn,false)}}
async function saveWeather(){if(!validateWeather())return;const btn=$('saveWeatherButton');$('weatherFormStatus').textContent='Test et application transactionnelle…';setBusy(btn,true,'Enregistrement…');try{const r=await api('/api/weather/config',{method:'POST',body:JSON.stringify(weatherBody())});const d=await r.json();if(!r.ok){$('weatherFormStatus').textContent=d.detail||'Échec';toast('bad','Configuration non appliquée',d.detail||'Erreur');return}$('apiKey').value='';$('weatherFormStatus').textContent='Configuration appliquée';toast('good','Weather mis à jour','Configuration sauvegardée et collector rechargé');await Promise.all([loadWeather(),loadServices()]);setTimeout(refreshStatus,350)}finally{setBusy(btn,false)}}
async function changePassword(){const current=$('currentPassword').value,newp=$('newPassword').value;if(newp.length<12){$('newPassword').classList.add('invalid');$('passwordError').textContent='12 caractères minimum';return}const btn=$('changePasswordButton');setBusy(btn,true,'Modification…');try{const r=await api('/api/auth/password',{method:'POST',body:JSON.stringify({current_password:current,new_password:newp})});const d=await r.json();if(!r.ok){$('passwordStatus').textContent=d.detail||'Échec';toast('bad','Mot de passe non modifié',d.detail||'Erreur');return}$('currentPassword').value='';$('newPassword').value='';$('newPassword').classList.remove('invalid');$('passwordError').textContent='';$('passwordStatus').textContent='Mot de passe modifié';toast('good','Mot de passe modifié')}finally{setBusy(btn,false)}}
async function refreshStatus(){const r=await api('/api/status');if(r.status===401){location.reload();return}if(r.ok)renderStatus(await r.json())}
document.querySelectorAll('.nav [data-view]').forEach(b=>b.onclick=()=>showView(b.dataset.view));document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>showView(b.dataset.go));$('loginButton').onclick=login;$('loginPassword').addEventListener('keydown',e=>{if(e.key==='Enter')login()});$('logout').onclick=logout;$('geocodeButton').onclick=geocode;$('testWeatherButton').onclick=testWeather;$('saveWeatherButton').onclick=saveWeather;$('testNewsButton').onclick=testNews;$('saveNewsButton').onclick=saveNews;$('newsMode').addEventListener('change',()=>{updateNewsMode();validateNews(false)});$('changePasswordButton').onclick=changePassword;['weatherEnabled','latitude','longitude','apiKey','lang','requestTimeout','currentMinutes','hourlyMinutes','dailyMinutes'].forEach(id=>$(id).addEventListener('input',()=>validateWeather(false)));['newsEnabled','newsQuery','newsLang','newsCountry','newsMaxArticles','newsIntervalMinutes','newsApiKey','newsRequestTimeout'].forEach(id=>$(id).addEventListener('input',()=>validateNews(false)));boot();setInterval(()=>{if(!$('app').classList.contains('hide'))refreshStatus()},30000);
</script></body></html>'''
